<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();$albumId=(int)($_GET['album_id']??0);require_album_access($albumId);$s=$pdo->prepare('SELECT * FROM albums WHERE id=?');$s->execute([$albumId]);$album=$s->fetch();if(!$album)redirect('admin/index.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$token=random_token(24);$expires=trim($_POST['expires_at'])?:null;$hash=trim($_POST['password'])!==''?password_hash($_POST['password'],PASSWORD_DEFAULT):null;$s=$pdo->prepare('INSERT INTO shares(album_id,token,label,password_hash,expires_at,allow_download) VALUES(?,?,?,?,?,?)');$s->execute([$albumId,$token,trim($_POST['label']),$hash,$expires,!empty($_POST['allow_download'])?1:0]);flash('success','Freigabelink erstellt.');redirect('admin/shares.php?album_id='.$albumId);} $s=$pdo->prepare('SELECT * FROM shares WHERE album_id=? ORDER BY created_at DESC');$s->execute([$albumId]);$shares=$s->fetchAll();render_header(t('page.shares.title'),true);?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1"><?=e(t('page.shares.title'))?></h1><p class="text-body-secondary mb-0"><?=e($album['title'])?></p></div><a class="btn btn-outline-secondary" href="album_edit.php?id=<?=$albumId?>"><?=e(t('text.zuruck'))?></a></div><div class="row g-4"><div class="col-lg-5"><div class="card shadow-sm"><div class="card-body"><h2 class="h5">Neuen Link erstellen</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="mb-3"><label class="form-label"><?=e(t('text.bezeichnung'))?></label><input class="form-control" name="label" placeholder="<?=e(t('text.z.b.kunde.veranstaltung'))?>"></div><div class="mb-3"><label class="form-label"><?=e(t('text.optionales.passwort'))?></label><input type="password" class="form-control" name="password"></div><div class="mb-3"><label class="form-label"><?=e(t('text.ablaufdatum'))?></label><input type="datetime-local" class="form-control" name="expires_at"></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="allow_download" id="d" checked><label class="form-check-label" for="d"><?=e(t('text.downloads.erlauben'))?></label></div><button class="btn btn-primary">Link erstellen</button></form></div></div></div><div class="col-lg-7"><div class="card shadow-sm"><div class="card-header"><?=e(t('text.aktiv'))?>e Freigaben</div><div class="list-group list-group-flush"><?php foreach($shares as $sh):$url=base_url('share.php?token='.$sh['token']);?><div class="list-group-item"><div class="fw-semibold"><?=e($sh['label']?:'Freigabe')?></div><div class="small share-url text-break my-2"><?=e($url)?></div><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-primary" onclick="navigator.clipboard.writeText('<?=e($url)?>')"><?=e(t('text.link.kopieren'))?></button><a class="btn btn-sm btn-outline-secondary" target="_blank" href="<?=e($url)?>"><?=e(t('text.offnen'))?></a></div></div><?php endforeach?><?php if(!$shares):?><div class="list-group-item text-body-secondary"><?=e(t('shares.none_short'))?></div><?php endif?></div></div></div></div><?php render_footer();
